        "context": "事務事業評価表\n施策名\n\n0101\n\n出会いと結婚の支援\n\n【事業類型】\n\n【事業概要シート作成有無】\n\n負担金のみの事業（イベント等の実行委員会への負担金を除く）\n\n4\n\n組織や職員を管理するための内部事務管理事務（財務事務、人事管理事務、企画事務、議会事務など）\n\n5\n\n施設の維持管理費のみの事業（光熱水費や法定の保守点検委託料など。施設の修繕料）\n\n6\n\n施設を維持管理するための運営業務（施設やそれに付随する車両等の運転業務委託、公園などの管理業務、清掃委託）\n\n7\n\n課内事務を行う上で必要となる事務的経費のみで構成される事業（条例委員の報酬、旅費、需要費、役務費のみで構成）\n\n8\n\n団体等への負担金及び補助金が予算の大半を占めるもの・・・補助金は、補助金要綱及び補助金等のあり方に関するガイドラインにおいて精査されている。\n\n9\n\nハード事業で、中長期の年度計画（事業費含む）を策定し認められた事業\n\n10\n\nハード事業1,000万円未満、ソフト事業100万未満（事業類型1～9以外）\n\n11\n\nハード事業1,000万円以上、ソフト事業100万円以上（事業類型1～9以外）\n\n＜総合評価＞\n\nａ…市が実施することが妥当である\n\nＡ…計画通りに事業を進めることが適当\n\nｂ…見直す余地がある\n\nＢ…事業の進め方の改善検討\n\nｃ…市が実施する緊急性が認められない\n\nＣ…事業規模・内容又は実施主体の見直しの検討\n\n有効性（施策貢献度）\n\nＹＥＳ\n\nＤ…事業の抜本的見直し、休・廃止の検討\n\nａ…施策への貢献度が高い\n\n【必 要 】\n\n3\n\nＮＯ\n\n事 業 概 要 シ ート\n\n国の法令に基づいて実施する事務（生活保護、賦課徴収事務、年金事務、戸籍・住基台帳事務、選挙事務、広域組合の負担金などの市の裁量が及ばない事務）\n\n妥当性（市の関与）\n\n【不 要 】\n\n2\n\n【事務事業評価の視点】\n事 業 概 要 シ ート\n\n職員人件費のみの事業\n\n新規・拡充・その他の見直し\n\n1\n\nｂ…施策への貢献度が著しく高いとはいえない\nｃ…成果の向上が見込まれない\n効率性（コスト）\nａ…コストを見直す余地がない\nｂ…検討する余地がある\n\n事業費は当初・繰越・補正予算の合計額\n担当課\nNO\n\n事業名\n\n課長\n\n事業内容\n\n事業期間\n\n事業費（千円）\n根拠法令\n要綱等\n\n事業\n類型\n\nＲ８\n\nＲ６\n\nＲ７\n\n決算\n\n予算\n\n見込\n\n決算\n\n予算\n\n6,283\n\n7,597\n\n6,171\n\n3,716\n\n3,716 成婚数\n\n2\n\n0\n\n0\n\n0\n\n0\n\n0\n\n3\n\n0\n\n0\n\n0\n\n0\n\n0\n\n4\n\n0\n\n0\n\n0\n\n0\n\n0\n\n5\n\n0\n\n0\n\n0\n\n0\n\n0\n\n6\n\n0\n\n0\n\n0\n\n0\n\n0\n\n7\n\n0\n\n0\n\n0\n\n0\n\n0\n\n8\n\n0\n\n0\n\n0\n\n0\n\n0\n\nこども政策課\n\n1\n\n結婚応援事業\n山口\n\n理行\n\n荒平\n\n亜美\n\n結婚に関する相談を行うとともに婚活イベントを開催するこ\nとにより、結婚を望む独身男女の出会いをサポートする。\n\n平成30年度\n\n効率性\n\n総合評価\n\nＲ６\n\nＲ７\n\n開始\n\n有効性\n\n終了\n・地域少子化対策重\n点推進交付金交付要\n綱\n・基地と地域との共\n存共生推進事業補助\n金\n\na\n\na\n\na\n\nA\n\n妥当\n\n貢献度高\n\n余地なし\n\n事業推進\n\n11\n\nＲ７\n\nＲ８\n\n計画\n\n実績\n\n計画\n\n計画\n\n16\n\n12\n\n17\n\n18\n\n人件費（千円）\n\nＲ６\n\n担当者\n\n妥当性\n\n主な指標\n\n単位\n\n組\n\n概要\n\n事業の方向性\n\nシート\n\n現状維持\n\n有",
